UPDATE hypervisor_resource
SET status = #{status}, resource_version = #{version}, updated_at = #{updatedAt}
WHERE hypervisor_id = #{hypervisorId} AND resource_version < #{version}

UPDATE hypervisor_host
SET running_vms = (
    SELECT COUNT(*) FROM instance_allocation
    WHERE hypervisor_id = #{hypervisorId} AND allocation_status = 'ALLOCATED'
)
WHERE id = #{hypervisorId}

UPDATE instance_allocation
SET allocation_status = 'RELEASED', resource_version = #{version}, updated_at = #{updatedAt}
WHERE instance_id = #{instanceId} AND resource_version < #{version}
